"""
Gera o dashboard HTML de KPIs do Motor CEVAP.

Indicadores:
- Taxa de conversao (global + por consultor: Filipe Paiva e Katia Almeida)
- Cobertura (% da base com tentativa de contato)
- Aging medio (dias entre publicacao e primeiro contato)
- Faturamento realizado (validado via cross-reference Protheus)
- Alertas de inconsistencia ativos
- Distribuicao por segmento (A1-C1)
"""
import base64
import json
from datetime import datetime
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).parents[1]
DATA_DIR = ROOT / "data"
OUTPUT_PATH = DATA_DIR / "output" / "daily_report_kpis.html"

ONEDRIVE_PATH = Path(r"C:\Users\victor.bernardi\OneDrive - INOVA EQUIPAMENTOS LTDA\Documentos\CEVAP_ATIVACAO.xlsx")
CONFIG_REGIOES = DATA_DIR / "config" / "regioes_consultores.json"
_BUP_LOG = Path(__file__).parents[2] / "BUP-base-unica-pós-venda" / "data" / "logs"

_LOGO_INOVA = Path(__file__).parents[2] / "apresentacao-roberto-1805" / "temp_charts" / "inova_logo_cdcdcd.png"
_LOGO_JD = Path(__file__).parents[2] / "apresentacao-roberto-2505" / "temp_charts" / "JD_logo_no_text.png"

SANIDADE_MIN_LINHAS = 100


def _logo_b64(path: Path) -> str:
    if not path.exists():
        return ""
    return "data:image/png;base64," + base64.b64encode(path.read_bytes()).decode()


def _resolver_fonte_dados(data_dir: Path, onedrive_path: Path) -> tuple:
    """Resolve a fonte de dados: output local -> OneDrive -> erro.

    Returns:
        (Path, None) se encontrou arquivo valido
        (None, str) se nenhum arquivo e valido (str = mensagem de erro)
    """
    # 1) Buscar output local mais recente
    outputs = sorted(
        data_dir.glob("CEVAP_ATIVACAO_*.xlsx"),
        key=lambda p: p.stem,
        reverse=True,
    )
    for output in outputs:
        try:
            total = len(pd.read_excel(output, usecols=[0]))
            if total >= SANIDADE_MIN_LINHAS:
                return output, None
        except Exception:
            continue

    # 2) Fallback OneDrive
    if onedrive_path.exists():
        try:
            total = len(pd.read_excel(onedrive_path, usecols=[0]))
            if total >= SANIDADE_MIN_LINHAS:
                return onedrive_path, None
        except Exception:
            pass

    # 3) Nenhum valido
    return None, "Nenhuma fonte de dados disponivel"


def _verificar_frescor_auditoria(output_path: Path, audit_path: Path, inconsist_path: Path) -> str:
    """Verifica se a auditoria Protheus esta fresca relativa ao output CEVAP.

    Returns:
        "Auditado" se ambos JSONs existem e sao mais novos que o output
        "Desatualizado" se algum JSON existe mas e mais antigo
        "Nao_Auditado" se nenhum JSON existe
    """
    ambos_existem = audit_path.exists() and inconsist_path.exists()
    algum_existe = audit_path.exists() or inconsist_path.exists()

    if not algum_existe:
        return "Nao_Auditado"

    output_ts = output_path.stat().st_mtime
    audit_ts = audit_path.stat().st_mtime if audit_path.exists() else 0
    inconsist_ts = inconsist_path.stat().st_mtime if inconsist_path.exists() else 0

    if ambos_existem and audit_ts >= output_ts and inconsist_ts >= output_ts:
        return "Auditado"

    return "Desatualizado"


def _carregar_entrada_dates() -> dict:
    path = _BUP_LOG / "cevap_entrada_dates.json"
    if not path.exists():
        print(f"AVISO: {path.name} nao encontrado — aging por JSON indisponivel.")
        return {}
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError) as e:
        print(f"AVISO: cevap_entrada_dates.json ilegivel: {e}")
        return {}


def _build_meso_consultor_map() -> dict[str, str]:
    """Le regioes_consultores.json e retorna {mesoregiao: nome_consultor}."""
    if not CONFIG_REGIOES.exists():
        return {}, None
    with open(CONFIG_REGIOES, encoding="utf-8") as f:
        cfg = json.load(f)
    mapa = {}
    fallback = None
    for c in cfg.get("consultores", []):
        regioes = c.get("mesorregioes", [])
        if regioes == "__demais__":
            fallback = c["nome"]
        else:
            for r in regioes:
                mapa[r] = c["nome"]
    return mapa, fallback


def _carregar_dados():
    meso_map, consultor_fallback = _build_meso_consultor_map()
    _consultores_lista = list(meso_map.values()) + ([consultor_fallback] if consultor_fallback else [])
    _consultores_unicos = list(dict.fromkeys(_consultores_lista)) or ["Filipe Paiva"]
    entrada_dates = _carregar_entrada_dates()

    dados = {
        "total_clientes": 0,
        "com_contato1": 0,
        "com_contato2": 0,
        "venda": 0,
        "nao_venda": 0,
        "sem_contato": 0,
        "pendente": 0,
        "vendas_declaradas": 0,
        "com_resposta": 0,
        "consultores_data": {nome: {"contatos": 0, "vendas": 0, "aging_dias": 0, "aging_count": 0} for nome in _consultores_unicos},
        "aging_total_dias": 0,
        "aging_count": 0,
        "segmentos": {},
        "mesorregioes": {},
        "inconsistencias": [],
        "conversoes": [],
        "faturamento_realizado": 0.0,
        "estado_auditoria": "Nao_Auditado",
        "fonte_info": "",
        "erro_fonte": None,
        "aging_json_ausente": False,
    }

    # RF-1: Fonte de dados hibrida
    fonte_path, erro = _resolver_fonte_dados(DATA_DIR, ONEDRIVE_PATH)
    if erro:
        dados["erro_fonte"] = erro
        return dados

    try:
        df = pd.read_excel(fonte_path)
    except Exception as exc:
        dados["erro_fonte"] = f"Falha ao ler {fonte_path.name}: {exc}"
        return dados

    dados["total_clientes"] = len(df)
    dados["data_planilha"] = datetime.now().strftime("%d/%m/%Y %H:%M")
    dados["fonte_info"] = fonte_path.stem

    # RF-3: Verificar frescor da auditoria
    audit_path = DATA_DIR / "conversao_audit.json"
    inconsist_path = DATA_DIR / "inconsistencias_venda.json"
    dados["estado_auditoria"] = _verificar_frescor_auditoria(fonte_path, audit_path, inconsist_path)

    # RF-2: Flag de aging JSON ausente
    if not entrada_dates:
        dados["aging_json_ausente"] = True

    # Contatos e status
    for _, row in df.iterrows():
        s1 = str(row.get("Status_Contato_1", "")).strip()
        s2 = str(row.get("Status_Contato_2", "")).strip()
        d1 = str(row.get("Data_Tentativa_1", "")).strip()
        d2 = str(row.get("Data_Tentativa_2", "")).strip()
        meso = str(row.get("Mesoregiao", "")).strip()
        consultor = meso_map.get(meso, consultor_fallback or _consultores_unicos[0])

        # Cobertura: ao menos uma tentativa registrada
        tentativas = []
        if d1 and d1 not in ("", "nan", "NaT"):
            dados["com_contato1"] += 1
            tentativas.append(d1)
        if d2 and d2 not in ("", "nan", "NaT"):
            dados["com_contato2"] += 1
            tentativas.append(d2)

        # RF-4: Vendas Declaradas
        is_venda = s1 == "Venda" or s2 == "Venda"
        if is_venda:
            dados["vendas_declaradas"] += 1

        # RF-5: Taxa de Resposta
        has_resposta = s1 not in ("", "nan", "NaT", "Pendente")
        if has_resposta:
            dados["com_resposta"] += 1

        # Atribuicao geografica por consultor
        cd = dados["consultores_data"].setdefault(consultor, {"contatos": 0, "vendas": 0, "aging_dias": 0, "aging_count": 0})
        if tentativas:
            cd["contatos"] += 1
        if is_venda:
            cd["vendas"] += 1

        # Status global
        status_final = s1 if s1 in ("Venda", "Nao Venda", "Sem Contato") else s2
        if status_final == "Venda":
            dados["venda"] += 1
        elif status_final == "Nao Venda":
            dados["nao_venda"] += 1
        elif status_final == "Sem Contato":
            dados["sem_contato"] += 1
        else:
            dados["pendente"] += 1

        # RF-2: Aging unificado via cevap_entrada_dates.json
        cnpj8 = str(row.get("CNPJ_Grupo", ""))[:8]
        data_str = entrada_dates.get(cnpj8)
        if data_str:
            try:
                dt_entrada = pd.Timestamp(data_str).to_pydatetime().replace(tzinfo=None)
                aging_dias = abs((datetime.now() - dt_entrada).days)
                dados["aging_total_dias"] += aging_dias
                dados["aging_count"] += 1
                cd["aging_dias"] += aging_dias
                cd["aging_count"] += 1
            except (ValueError, TypeError):
                pass

        # Segmento
        seg = str(row.get("Classificacao", "N/A")).strip()
        if seg:
            dados["segmentos"][seg] = dados["segmentos"].get(seg, 0) + 1

        # Mesorregiao
        meso = str(row.get("Mesoregiao", "Indisponivel")).strip()
        if meso and meso != "Indisponivel":
            dados["mesorregioes"][meso] = dados["mesorregioes"].get(meso, 0) + 1

    # Carregar cross-reference (apenas se auditado)
    if dados["estado_auditoria"] in ("Auditado", "Desatualizado"):
        if audit_path.exists():
            try:
                with open(audit_path, "r", encoding="utf-8") as f:
                    conversoes = json.load(f)
                dados["conversoes"] = list(conversoes.values())
                dados["faturamento_realizado"] = sum(c.get("valor_liquido", 0) for c in conversoes.values())
            except Exception:
                pass

        if inconsist_path.exists():
            try:
                with open(inconsist_path, "r", encoding="utf-8") as f:
                    dados["inconsistencias"] = list(json.load(f).values())
            except Exception:
                pass

    return dados


def gerar_html():
    d = _carregar_dados()

    total = d["total_clientes"]
    cobertura_pct = round((d["com_contato1"] / total * 100) if total > 0 else 0, 1)
    resposta_pct = round((d["com_resposta"] / total * 100) if total > 0 else 0, 1)
    vendas_declaradas = d["vendas_declaradas"]
    taxa_declarada = round((vendas_declaradas / total * 100) if total > 0 else 0, 1)
    aging_medio = round(d["aging_total_dias"] / d["aging_count"], 1) if d["aging_count"] > 0 else 0
    fat_realizado = d["faturamento_realizado"]
    estado_auditoria = d["estado_auditoria"]
    conversao_pct = round((len(d["conversoes"]) / total * 100) if total > 0 else 0, 1)

    # Cards Protheus so aparecem se auditado
    protheus_disponivel = estado_auditoria == "Auditado" and total > 0

    # Contato por consultor (dinamico)
    consultores_data = d["consultores_data"]

    # Segmentos - criar rows HTML
    seg_rows = ""
    for seg in ["A1", "A2", "B1", "B2", "C1"]:
        qtd = d["segmentos"].get(seg, 0)
        pct = round(qtd / total * 100, 1) if total > 0 else 0
        seg_rows += f"""
                    <tr>
                        <td>{seg}</td>
                        <td style="text-align: right; font-weight: 600;">{qtd}</td>
                        <td style="text-align: right;">{pct}%</td>
                    </tr>"""

    # Mesorregioes rows
    meso_rows = ""
    meso_sorted = sorted(d["mesorregioes"].items(), key=lambda x: -x[1])[:10]
    for meso, qtd in meso_sorted:
        meso_rows += f"""
                    <tr>
                        <td>{meso}</td>
                        <td style="text-align: right; font-weight: 600;">{qtd}</td>
                    </tr>"""

    # Inconsistencias alerts (apenas se auditado)
    inconsist_html = ""
    if estado_auditoria == "Auditado":
        if d["inconsistencias"]:
            inconsist_items = ""
            for inc in d["inconsistencias"][:10]:
                inconsist_items += f"""
                    <tr>
                        <td>{inc.get('cnpj', 'N/A')}</td>
                        <td>{inc.get('nome_cliente', 'N/A')[:50]}</td>
                        <td>{inc.get('motivo', 'N/A')}</td>
                    </tr>"""
            inconsist_html = f"""
            <div class="highlight-box alert-box">
                <b>Atencao: {len(d['inconsistencias'])} inconsistencias ativas:</b> Clientes com status "Venda" sem validacao de nota fiscal no Protheus. Verifique.
            </div>
            <table class="data-table">
                <thead>
                    <tr>
                        <th>CNPJ</th>
                        <th>Cliente</th>
                        <th>Motivo</th>
                    </tr>
                </thead>
                <tbody>{inconsist_items}
                </tbody>
            </table>"""
        else:
            inconsist_html = """
            <div class="highlight-box success-box">
                <b>Todas as vendas validadas:</b> Nenhuma inconsistencia ativa. Todos os clientes com status "Venda" possuem nota fiscal confirmada no Protheus.
            </div>"""

    # Cards Protheus condicionais
    protheus_cards = ""
    if protheus_disponivel:
        protheus_cards = f"""
                <div class="kpi-card success">
                    <span class="kpi-title">Conversao (Protheus)</span>
                    <span class="kpi-value">{conversao_pct}%</span>
                    <span class="kpi-desc">{len(d['conversoes'])} vendas validadas no Protheus</span>
                </div>
                <div class="kpi-card success">
                    <span class="kpi-title">Faturamento (Protheus)</span>
                    <span class="kpi-value">R$ {fat_realizado:,.2f}</span>
                    <span class="kpi-desc">Volume total validado de vendas CEVAP</span>
                </div>"""

    # Banner de estado da fonte
    if d.get("erro_fonte"):
        banner_html = f"""
            <div class="highlight-box alert-box">
                <b>Erro:</b> {d['erro_fonte']}. O dashboard nao foi gerado.
            </div>"""
    else:
        fonte_label = "output local" if "CEVAP_ATIVACAO" in d.get("fonte_info", "") else "OneDrive (fallback)"
        banner_html = f"""
            <div class="highlight-box" style="background-color: #F8FAFC; border-left: 4px solid #1F2937; color: #1F2937;">
                <b>Fonte:</b> {fonte_label} — {d.get('fonte_info', 'N/A')}
            </div>"""

    # Banner de auditoria — omitido quando ainda nao rodado
    if estado_auditoria == "Nao_Auditado":
        audit_html = ""
    elif estado_auditoria == "Desatualizado":
        audit_html = """
            <div class="highlight-box audit-box">
                <b>Auditoria Protheus desatualizada:</b> A consolidacao e mais recente que a ultima auditoria. Rode <code>cross_reference_protheus.py</code>.
            </div>"""
    else:
        audit_html = """
            <div class="highlight-box success-box">
                <b>Auditoria Protheus:</b> Todas as vendas foram validadas contra notas fiscais.
            </div>"""

    # Banner de aging JSON ausente
    aging_aviso = ""
    if d.get("aging_json_ausente"):
        aging_aviso = """
            <div class="highlight-box audit-box">
                <b>Aviso:</b> cevap_entrada_dates.json nao encontrado. Aging indisponivel.
            </div>"""

    aging_status = "Excelente (< 4 dias)" if aging_medio < 4 else ("Atencao (4-7 dias)" if aging_medio < 7 else "Critico (> 7 dias)")
    aging_color = "#22C55E" if aging_medio < 4 else ("#FFC20E" if aging_medio < 7 else "#EF4444")

    logo_inova_src = _logo_b64(_LOGO_INOVA)
    logo_jd_src = _logo_b64(_LOGO_JD)
    logo_inova_html = f'<img src="{logo_inova_src}" alt="Inova">' if logo_inova_src else ""
    logo_jd_html = f'<img src="{logo_jd_src}" alt="John Deere">' if logo_jd_src else ""
    consultores_nomes = " · ".join(consultores_data.keys()) if consultores_data else "N/A"
    data_relatorio = datetime.now().strftime("%d/%m/%Y")

    html = f"""<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Daily Report - Motor CEVAP</title>
    <style>
        body {{
            font-family: 'Segoe UI', Arial, sans-serif;
            background-color: #F1F3F5;
            color: #333333;
            margin: 0;
            padding: 0;
        }}
        .container {{
            max-width: 900px;
            margin: 20px auto;
            background-color: #FFFFFF;
            border-radius: 8px;
            box-shadow: 0 4px 16px rgba(0,0,0,0.10);
            overflow: hidden;
            border: 1px solid #E1E6EB;
        }}
        .header {{
            background: linear-gradient(135deg, #1F2937 0%, #18181B 100%);
            padding: 28px 40px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 20px;
        }}
        .header-logos {{
            display: flex;
            align-items: center;
            gap: 16px;
            min-width: 80px;
        }}
        .header-logos img {{
            height: 40px;
            object-fit: contain;
        }}
        .header-text {{
            flex: 1;
            text-align: center;
        }}
        .header-text h1 {{
            margin: 0;
            font-size: 22px;
            font-weight: 700;
            color: #FFFFFF;
            letter-spacing: 0.5px;
        }}
        .header-text p {{
            margin: 4px 0 0 0;
            font-size: 13px;
            color: #9CA3AF;
        }}
        .meta-bar {{
            background-color: #1F2937;
            border-top: 1px solid #374151;
            padding: 10px 40px;
            display: flex;
            gap: 32px;
            flex-wrap: wrap;
        }}
        .meta-item {{
            font-size: 12px;
            color: #9CA3AF;
        }}
        .meta-item span {{
            color: #FFC20E;
            font-weight: 600;
        }}
        .content {{
            padding: 40px;
        }}
        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
            margin-bottom: 35px;
        }}
        @media (max-width: 600px) {{
            .kpi-grid {{
                grid-template-columns: 1fr;
            }}
        }}
        .kpi-card {{
            background-color: #FAFCFF;
            border: 1px solid #E8F0F8;
            border-radius: 6px;
            padding: 20px;
            display: flex;
            flex-direction: column;
            border-left: 4px solid #FFC20E;
            transition: transform 0.2s ease;
        }}
        .kpi-card.success {{
            border-left-color: #22C55E;
            background-color: #F7FAF7;
            border-color: #D1FAE5;
        }}
        .kpi-card.warning {{
            border-left-color: #FFC20E;
            background-color: #FFFBEB;
            border-color: #FEF3C7;
        }}
        .kpi-title {{
            font-size: 12px;
            font-weight: 600;
            color: #7A8B9E;
            text-transform: uppercase;
            letter-spacing: 0.8px;
            margin-bottom: 8px;
        }}
        .kpi-value {{
            font-size: 28px;
            font-weight: 700;
            color: #1F2937;
            margin-bottom: 5px;
        }}
        .kpi-card.success .kpi-value {{
            color: #22C55E;
        }}
        .kpi-desc {{
            font-size: 12px;
            color: #6B7C93;
        }}
        .section-title {{
            font-size: 18px;
            font-weight: 600;
            color: #1F2937;
            border-bottom: 2px solid #FFC20E;
            padding-bottom: 8px;
            margin-bottom: 20px;
            margin-top: 40px;
        }}
        .data-table {{
            width: 100%;
            border-collapse: collapse;
            margin-top: 15px;
            font-size: 14px;
        }}
        .data-table th {{
            background-color: #1F2937;
            font-weight: 600;
            color: #FFC20E;
            text-align: left;
            padding: 12px 15px;
            border-bottom: 2px solid #374151;
        }}
        .data-table td {{
            padding: 12px 15px;
            border-bottom: 1px solid #EEF2F6;
            color: #4A5568;
        }}
        .footer {{
            background-color: #1F2937;
            padding: 18px 40px;
            font-size: 12px;
            color: #9CA3AF;
            text-align: center;
            border-top: 1px solid #374151;
        }}
        .highlight-box {{
            padding: 15px 20px;
            border-radius: 4px;
            margin-bottom: 30px;
            font-size: 14px;
            line-height: 1.5;
        }}
        .highlight-box.audit-box {{
            background-color: #FFFBEB;
            border-left: 4px solid #FFC20E;
            color: #92400E;
        }}
        .highlight-box.alert-box {{
            background-color: #FEF2F2;
            border-left: 4px solid #EF4444;
            color: #7F1D1D;
            margin-top: 15px;
        }}
        .highlight-box.success-box {{
            background-color: #F0FDF4;
            border-left: 4px solid #22C55E;
            color: #14532D;
        }}
        .consultant-grid {{
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px;
            margin-bottom: 25px;
        }}
        .consultant-card {{
            background-color: #FAFCFF;
            border: 1px solid #E8F0F8;
            border-radius: 6px;
            padding: 20px;
        }}
        .consultant-card h3 {{
            margin: 0 0 15px 0;
            font-size: 16px;
            color: #1F2937;
            border-bottom: 2px solid #FFC20E;
            padding-bottom: 8px;
        }}
        .consultant-stat {{
            display: flex;
            justify-content: space-between;
            padding: 6px 0;
            border-bottom: 1px solid #EEF2F6;
            font-size: 13px;
        }}
        .consultant-stat:last-child {{
            border-bottom: none;
        }}
        .stat-label {{
            color: #7A8B9E;
        }}
        .stat-value {{
            font-weight: 600;
            color: #1F2937;
        }}
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <div class="header-logos">
                {logo_inova_html}
            </div>
            <div class="header-text">
                <h1>Report de Ativacao CEVAP</h1>
                <p>Campanha de Reativacao — Pos-Vendas Inova</p>
            </div>
            <div class="header-logos">
                {logo_jd_html}
            </div>
        </div>
        <div class="meta-bar">
            <div class="meta-item">Campanha <span>Clientes +90 dias sem compra</span></div>
            <div class="meta-item">Consultores <span>{consultores_nomes}</span></div>
            <div class="meta-item">Base <span>{total} clientes</span></div>
            <div class="meta-item">Referencia <span>{data_relatorio}</span></div>
        </div>
        <div class="content">
            {banner_html}
            {aging_aviso}
            {audit_html}

            <div class="section-title">Indicadores de Desempenho (KPIs)</div>
            <div class="kpi-grid">
                <div class="kpi-card">
                    <span class="kpi-title">Cobertura</span>
                    <span class="kpi-value">{cobertura_pct}%</span>
                    <span class="kpi-desc">{d['com_contato1']} de {total} clientes com ao menos 1 tentativa</span>
                </div>
                <div class="kpi-card">
                    <span class="kpi-title">Taxa de Resposta</span>
                    <span class="kpi-value">{resposta_pct}%</span>
                    <span class="kpi-desc">{d['com_resposta']} clientes com resultado registrado</span>
                </div>
                <div class="kpi-card">
                    <span class="kpi-title">Aging Medio</span>
                    <span class="kpi-value">{aging_medio} dias</span>
                    <span class="kpi-desc">Tempo medio na fila CEVAP</span>
                </div>
                <div class="kpi-card success">
                    <span class="kpi-title">Vendas Declaradas</span>
                    <span class="kpi-value">{vendas_declaradas}</span>
                    <span class="kpi-desc">{taxa_declarada}% — vendas auto-reportadas pelos consultores</span>
                </div>
                {protheus_cards}
            </div>

            <div class="section-title">Desempenho por Consultor CEVAP</div>
            <div class="consultant-grid">
                {"".join(
                    f'<div class="consultant-card">'
                    f'<h3>{nome}</h3>'
                    f'<div class="consultant-stat"><span class="stat-label">Clientes contatados</span><span class="stat-value">{cd["contatos"]}</span></div>'
                    f'<div class="consultant-stat"><span class="stat-label">Vendas registradas</span><span class="stat-value">{cd["vendas"]}</span></div>'
                    f'<div class="consultant-stat"><span class="stat-label">Taxa de conversao</span><span class="stat-value">{round(cd["vendas"] / cd["contatos"] * 100, 1) if cd["contatos"] > 0 else 0}%</span></div>'
                    f'<div class="consultant-stat"><span class="stat-label">Aging medio</span><span class="stat-value">{round(cd["aging_dias"] / cd["aging_count"], 1) if cd["aging_count"] > 0 else "N/A"} {"dias" if cd["aging_count"] > 0 else ""}</span></div>'
                    '</div>'
                    for nome, cd in consultores_data.items()
                )}
            </div>

            <div class="section-title">Distribuicao por Classificacao</div>
            <table class="data-table">
                <thead>
                    <tr>
                        <th>Segmento</th>
                        <th style="text-align: right;">Clientes</th>
                        <th style="text-align: right;">% da Base</th>
                    </tr>
                </thead>
                <tbody>{seg_rows}
                </tbody>
            </table>

            <div class="section-title">Metodologia e Aging Comercial</div>
            <table class="data-table">
                <thead>
                    <tr>
                        <th>Metrica de Operacao</th>
                        <th style="text-align: right;">Resultado</th>
                        <th>Status</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>Aging Medio na Fila CEVAP</td>
                        <td style="text-align: right; font-weight: 600;">{aging_medio} dias</td>
                        <td><span style="color: {aging_color}; font-weight: 600;">{aging_status}</span></td>
                    </tr>
                    <tr>
                        <td>Clientes Ativos na Fila CEVAP</td>
                        <td style="text-align: right; font-weight: 600;">{total} clientes</td>
                        <td><span style="color: #FFC20E; font-weight: 600;">Em aberto para consultores</span></td>
                    </tr>
                    <tr>
                        <td>Clientes com 1a Tentativa Realizada</td>
                        <td style="text-align: right; font-weight: 600;">{d['com_contato1']}</td>
                        <td><span style="color: #1F2937; font-weight: 600;">{list(consultores_data.keys())[0] if consultores_data else ""}</span></td>
                    </tr>
                    <tr>
                        <td>Clientes com 2a Tentativa Realizada</td>
                        <td style="text-align: right; font-weight: 600;">{d['com_contato2']}</td>
                        <td><span style="color: #1F2937; font-weight: 600;">{list(consultores_data.keys())[1] if len(consultores_data) > 1 else ""}</span></td>
                    </tr>
                </tbody>
            </table>

            {inconsist_html}
        </div>
        <div class="footer">
            Inova Maquinas - Motor CEVAP - Infraestrutura Cognitiva & Automacao de Processos 2026<br>
            Relatorio gerado em: {d.get('data_planilha', datetime.now().strftime('%d/%m/%Y %H:%M'))}
        </div>
    </div>
</body>
</html>"""

    OUTPUT_PATH.parent.mkdir(exist_ok=True)
    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        f.write(html)

    print(f"[OK] Dashboard gerado: {OUTPUT_PATH}")
    print(f"     Total clientes: {total}")
    print(f"     Cobertura: {cobertura_pct}%")
    print(f"     Vendas declaradas: {vendas_declaradas}")
    print(f"     Taxa de resposta: {resposta_pct}%")
    print(f"     Aging medio: {aging_medio} dias")
    print(f"     Estado auditoria: {estado_auditoria}")
    print(f"     Faturamento realizado: R$ {fat_realizado:,.2f}")


if __name__ == "__main__":
    gerar_html()

# Windows PowerShell 5.1+ Orquestrador do Report Diário (Daily SMTP) - CEVAP
$ErrorActionPreference = "Stop"
$ProjectRoot = "C:\Projetos\Inova\projects\motor-cevap"
$EnvPath = Join-Path $ProjectRoot ".env"
$PythonExe = Join-Path $ProjectRoot ".venv\Scripts\python.exe"
$RunScript = Join-Path $ProjectRoot "scripts\consolidate_cevap.py"
$KpiScript = Join-Path $ProjectRoot "scripts\generate_cevap_kpis.py"
$ReportHtml = Join-Path $ProjectRoot "data\output\daily_report_kpis.html"

# Carregar variáveis do arquivo .env
$EnvConfig = @{}
if (Test-Path $EnvPath) {
    Get-Content $EnvPath | ForEach-Object {
        $line = $_.Trim()
        if ($line -and -not $line.StartsWith("#") -and $line.Contains("=")) {
            $key, $value = $line.Split("=", 2)
            $EnvConfig[$key.Trim()] = $value.Trim()
        }
    }
}

# 1. Executa consolidação de dados e geração do HTML
& $PythonExe $RunScript
& $PythonExe $KpiScript

# 2. Envia e-mail
if (Test-Path $ReportHtml) {
    $HtmlBody = Get-Content -Path $ReportHtml -Raw -Encoding UTF8
    $SmtpServer = $EnvConfig["SMTP_SERVER"]
    if (-not $SmtpServer) { $SmtpServer = "smtp.office365.com" }
    $SmtpPort = 587
    if ($EnvConfig["SMTP_PORT"]) { $SmtpPort = [int]$EnvConfig["SMTP_PORT"] }
    $SmtpUser = $EnvConfig["SMTP_USER"]
    $SmtpPassword = $EnvConfig["SMTP_PASSWORD"]

    if ($SmtpUser -and $SmtpPassword -and $SmtpUser -ne "seu-email@inovamaquinas.com.br") {
        try {
            $SMTPClient = New-Object Net.Mail.SmtpClient($SmtpServer, $SmtpPort)
            $SMTPClient.EnableSsl = $true
            $SMTPClient.Credentials = New-Object System.Net.NetworkCredential($SmtpUser, $SmtpPassword)

            $MailMessage = New-Object Net.Mail.MailMessage
            $MailMessage.From = $SmtpUser
            $MailMessage.Subject = "Daily Report - Motor CEVAP - Ativacao de Inativos Inova"
            $MailMessage.Body = $HtmlBody
            $MailMessage.IsBodyHtml = $true

            $MailMessage.To.Add("roberto.reis@inovamaquinas.com.br")
            $MailMessage.To.Add("gabriela.rodarte@inovamaquinas.com.br")
            $MailMessage.To.Add("victor.bernardi@inovamaquinas.com.br")

            $SMTPClient.Send($MailMessage)
            Write-Host "Email enviado com sucesso!"
        } catch {
            Write-Warning "Falha no envio do e-mail SMTP: $_"
        }
    } else {
        Write-Host "[DRY-RUN] Simulação: Credenciais SMTP não configuradas. HTML salvo em $ReportHtml"
    }
}

